SELECT *, COUNT(amount) OVER w_running AS running_count_amount, SUM(amount) OVER w_running AS running_sum_amount, MAX(amount) OVER w_running AS running_max_amount, AVG(amount) OVER (PARTITION BY order_id ORDER BY CAST(paid_at AS BIGINT) RANGE BETWEEN 2592000 PRECEDING AND CURRENT ROW) AS amount_avg_30d FROM payments WHERE paid_at >= '2023-03-18' WINDOW w_running AS (PARTITION BY status ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
